'',
unistr('<dl><dt>\8981\5728\5458\5DE5\4F4D\4E8E\90E8\95E8 30 \65F6\8FD4\56DE "YES"\FF0C\8BF7\4F7F\7528\4EE5\4E0B\8BED\53E5\FF1A</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
