,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \4E3A\6B64 HTTP \64CD\4F5C\5206\914D<strong>\6570\636E\5E93\64CD\4F5C</strong>\3002\8981\5C06 &PRODUCT_NAME. \7EC4\4EF6\4E0E REST \6570\636E\6E90\4E00\8D77\4F7F\7528\FF0C\6570\636E\5E93\64CD\4F5C\5F88\91CD\8981\3002\4E3A\4E00\4E2A &PRODUCT_NAME. \7EC4\4EF6\5206\914D\4E00\4E2A REST \6570\636E\6E90\FF08\800C\4E0D\662F\4E00\4E2A\64CD\4F5C\FF09\FF0C\8FD9\6837\5B83\53EF\6839\636E\6240\9700\7684\6570\636E\5E93\64CD\4F5C\67E5\627E HTTP \64CD\4F5C\3002'),
'</p>',
'<ul>',
unistr('    <li>\53EF\89C6\5316\7EC4\4EF6\FF08\4F8B\5982\62A5\8868\3001\56FE\8868\3001CSS \65E5\5386\7B49\FF09\5C06\59CB\7EC8\4F7F\7528\5206\914D\7ED9<strong>\63D0\53D6\884C</strong>\6570\636E\5E93\64CD\4F5C\7684 HTTP \64CD\4F5C\3002<strong>APEX_EXEC.OPEN_WEB_SOURCE_QUERY</strong> \4E5F\5C06\4F7F\7528\201C\63D0\53D6\884C\201D\6570\636E\5E93\64CD\4F5C\3002</li>'),
unistr('    <li>\8868\5355\7EC4\4EF6\63D2\5165\3001\66F4\65B0\6216\5220\9664\884C\65F6\FF0C\5B83\5C06\5206\522B\4F7F\7528\5206\914D\7ED9<strong>\63D2\5165\884C</strong>\3001<strong>\66F4\65B0\884C</strong>\6216<strong>\5220\9664\884C</strong>\7684\64CD\4F5C\3002\5728 PL/SQL \4E2D\FF0C<strong>APEX_EXEC.OPEN_WEB_SOURCE_DML_CONTEXT</strong> \7B49\540C\4E8E\8868\5355\3002</li>'),
unistr('    <li>\5728\6267\884C\4E22\5931\66F4\65B0\68C0\6D4B\6216\5141\8BB8\7684\64CD\4F5C\68C0\67E5\65F6\FF0C\8868\5355\7EC4\4EF6\4F7F\7528<strong>\63D0\53D6\5355\884C</strong>\6570\636E\5E93\64CD\4F5C\3002\7136\540E\FF0C\5728\6267\884C\5B9E\9645\7684 DML \64CD\4F5C\4E4B\524D\FF0C\8868\5355\4F7F\7528\6B64\64CD\4F5C\4ECE REST \670D\52A1\91CD\65B0\63D0\53D6\884C\3002</li>'),
unistr('    <li>&PRODUCT_NAME. \7EC4\4EF6\4E0D\4F1A\4F7F\7528\672A\6620\5C04\5230\6570\636E\5E93\64CD\4F5C\7684\64CD\4F5C\3002\53EF\4F7F\7528 <strong>APEX_EXEC.EXECUTE_WEB_SOURCE</strong> PL/SQL \8FC7\7A0B\4ECE PL/SQL \4E0A\4E0B\6587\6267\884C\8FD9\4E9B\64CD\4F5C\3002</li>'),
'</ul>',
'<p>',
'    <br>',
unistr('    \4F8B\5982\FF0C&PRODUCT_NAME. \7684\62A5\8868\6216\56FE\8868\7EC4\4EF6\9700\8981\884C\96C6\5408\3002\4F7F\7528 REST \6570\636E\6E90\65F6\FF0C'),
unistr('    &PRODUCT_NAME. \5C06\5728\8FD0\884C\65F6\67E5\627E<strong>\63D0\53D6\884C</strong>\6570\636E\5E93\64CD\4F5C\5E76\6267\884C\5206\914D\7684 HTTP \64CD\4F5C\3002'),
unistr('    \8868\5355\5C06\67E5\627E\201C\63D2\5165\884C\201D\3001\201C\66F4\65B0\884C\201D\6216\201C\5220\9664\884C\201D\6570\636E\5E93\64CD\4F5C\3002'),
