,p_name=>'PE.PROPERTY.DB_SESSION_CLEANUP.HELP'
,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\4F7F\7528\6B64\5C5E\6027\53EF\8F93\5165\5728\9875\5904\7406\7ED3\675F\65F6\8FD0\884C\7684 PL/SQL \5757\3002'),
unistr('\5B83\53EF\7528\4E8E\91CA\653E\6216\6E05\9664\4F7F\7528\8FC7\7684\8D44\6E90, \4F8B\5982 VPD \4E0A\4E0B\6587\6216\6570\636E\5E93\94FE\63A5\3002'),
'</p>',
unistr('<p>\793A\4F8B 1:'),
'<pre>',
'dbms_session.clear_context(''CTX_USER_QRY'');',
'</pre>',
unistr('\6B64\8C03\7528\5728\5C06\6570\636E\5E93\4F1A\8BDD\8FD4\56DE\5230\4F1A\8BDD\6C60\4E4B\524D, \91CD\7F6E\540D\4E3A CTX_USER_QRY \7684\5E94\7528\7A0B\5E8F\4E0A\4E0B\6587,'),
unistr('\4ECE\800C\786E\4FDD\4EE5\540E\5728\91CD\7528\4F1A\8BDD\65F6\4E0D\4F1A\6CC4\6F0F\4EFB\4F55\4FE1\606F\3002'),
'</p>',
unistr('<p>\793A\4F8B 2:'),
'<pre>',
'dbms_session.close_database_link(''SALES'');',
'</pre>',
unistr('\6B64\8C03\7528\5173\95ED\6570\636E\5E93\94FE\63A5 SALES, \8BE5\94FE\63A5\53EF\80FD\5DF2\5728 "\521D\59CB\5316 PL/SQL \4EE3\7801" \4E2D\6253\5F00, \6216\8005\53EA\9700\901A\8FC7\94FE\63A5\67E5\8BE2\6570\636E\5C31\4F1A\9690\5F0F\6253\5F00\3002'),
unistr('\540C\6837, \8FD9\4F1A\91CA\653E\8D44\6E90\5E76\5728\91CD\7528\6570\636E\5E93\4F1A\8BDD\65F6\9632\6B62\8D44\6E90\6CC4\6F0F\3002'),
'</p>'))
,p_version_scn=>2565936
);
