wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(118535485574666697)
,p_name=>'PE.PROPERTY.DB_SESSION_INIT.HELP'
,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\4F7F\7528\6B64\5C5E\6027\53EF\4EE5\8F93\5165 PL/SQL \5757, \8BE5 PL/SQL \5757\8BBE\7F6E\4E0E\5F53\524D "\663E\793A\9875" \6216 "\63A5\53D7\9875" \8BF7\6C42\76F8\5173\8054\7684\6570\636E\5E93\4F1A\8BDD\7684\4E0A\4E0B\6587\3002\6B64\5904\8F93\5165\7684\5757\5728\9875\8BF7\6C42\671F\95F4\7684\5F88\65E9\65F6\95F4\70B9\6267\884C, \7D27\968F\5728 <code>APP_USER</code> \503C\5EFA\7ACB\4E4B\540E\3002<code>APP_USER</code> (\4F7F\7528 <code>:APP_USER</code> \6216 <code>v(''APP_USER'')</code>) \7684\503C\53EF\4EE5\5728\5757\4E2D\4F7F\7528\3002\4F1A\8BDD\72B6\6001\4E2D\5176\4ED6\9879\7684\503C\4E5F\53EF\5F15\7528, \4F46\4EFB\4F55\6B64\7C7B\9879\5FC5\987B\5728\5F53\524D\9875\8BF7\6C42\542F\52A8\4E4B\524D\5DF2\5728\4F1A\8BDD')
||unistr('\72B6\6001\4E2D\5EFA\7ACB\3002'),
unistr('\8BF7\8003\8651\4EE5\4E0B\793A\4F8B:'),
'</p>',
'<pre>',
'dbms_session.set_context(''CTX_USER_QRY'',''USERPRIV'',my_package.my_function(:APP_USER));',
'</pre>',
'',
unistr('<p>\6B64\793A\4F8B\5728\540D\4E3A <code>CTX_USER_QRY</code> \7684\4E0A\4E0B\6587\4E2D\5C06 <code>USERPRIV</code> \7684\503C\8BBE\7F6E\4E3A\7A0B\5E8F\5305 <code>my_package</code> \4E2D\51FD\6570 <code>my_function</code> \8FD4\56DE\7684\503C\3002<code>APP_USER</code> \7684\5F53\524D\503C\5C06\4F5C\4E3A\8F93\5165\53C2\6570\4F20\9012\7ED9\6B64\51FD\6570\3002\56E0\6B64, \547D\540D\4E0A\4E0B\6587\5C06\5728 VPD \7B56\7565 (\5DF2\7ECF\5728\5E94\7528\7A0B\5E8F\7684\8BED\6CD5\5206\6790\65B9\6848\4E2D\521B\5EFA) \4E2D\4F7F\7528\4EE5\751F\6210\9002\7528\4E8E\5DF2\9A8C\8BC1\7528\6237\7684\8C13\8BCD\3002</p>'),
'',
unistr('<p>\865A\62DF\4E13\7528\6570\636E\5E93, \4E5F\79F0\4E3A\7EC6\7C92\5EA6\8BBF\95EE\63A7\5236\6216 FGAC, \662F\4E00\79CD Oracle \6570\636E\5E93\529F\80FD, \5B83\63D0\4F9B\4E86\4E00\4E2A\5E94\7528\7A0B\5E8F\7F16\7A0B\63A5\53E3 (API), \4F7F\5F00\53D1\8005\53EF\4EE5\5411\6570\636E\5E93\8868\548C\89C6\56FE\5206\914D\5B89\5168\7B56\7565\3002\5229\7528 PL/SQL, \5F00\53D1\8005\53EF\4EE5\901A\8FC7\5B58\50A8\8FC7\7A0B\521B\5EFA\5B89\5168\7B56\7565\5E76\501F\52A9 RDBMS \7A0B\5E8F\5305\8C03\7528\7684\65B9\5F0F\5C06\8FC7\7A0B\7ED1\5B9A\5230\8868\6216\89C6\56FE\3002\6B64\7C7B\7B56\7565\57FA\4E8E\6570\636E\5E93\4E2D\5B58\50A8\7684\5E94\7528\7A0B\5E8F\6570\636E\7684\5185\5BB9, \6216\57FA\4E8E Oracle \6570\636E\5E93\63D0\4F9B\7684\4E0A\4E0B\6587\53D8\91CF\3002VPD \4EE5\8FD9\79CD\65B9\5F0F\5141\8BB8\8BBF\95EE\5B89\5168\673A\5236\4ECE\5E94\7528\7A0B\5E8F\4E2D\53BB\9664, \4ECE\800C\66F4\8D34\8FD1\7279\5B9A\65B9\6848\3002</p>'),
'',
unistr('<p>\6B64\5904\8F93\5165\7684\4EE3\7801\65E0\9700\4E0E VPD/FGAC \76F8\5173, \5E76\4E14\53EF\80FD\4E0E\5B89\5168\6027\5B8C\5168\65E0\5173\3002\53EF\4EE5\5C06\4EFB\4F55\9700\8981\5728\9875\8BF7\6C42\4E2D\6700\5148\6267\884C\7684\4EE3\7801\653E\7F6E\5728\6B64\5904\3002\4F8B\5982, \4EE5\4E0B\4EE3\7801\4E3A\6BCF\4E2A\9875\8BF7\6C42\8BBE\7F6E\6570\636E\5E93\4F1A\8BDD\65F6\533A:</p>'),
'',
'<pre>',
'BEGIN',
'   EXECUTE IMMEDIATE ''alter session set time_zone = ''''Australia/Sydney'''' '';',
'END;',
'</pre>'))
,p_version_scn=>2565936
);
