,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\67E5\8BE2\8FD4\56DE NUMBER \5217\4EE5\786E\5B9A\521D\59CB\5730\56FE\4F4D\7F6E\548C\7F29\653E\7EA7\522B\FF1A</p>'),
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
unistr('<p>\67E5\8BE2\8FD4\56DE SDO_GEOMETRY \5217\4EE5\786E\5B9A\521D\59CB\5730\56FE\4F4D\7F6E\FF0C\8FD4\56DE NUMBER \5217\4EE5\786E\5B9A\7F29\653E\7EA7\522B\3002</p>'),
'<pre>',
'select sdo_geometry( 2001,                                 -- 2 dimensional point',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     sdo_point_type( -133.5, 35.2, null ), -- concrete coordinates',
'                     null,                                 -- not used for points',
'                     null                                  -- not used for points',
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2566034
);
