wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(118645178650666730)
,p_name=>'PE.PROPERTY.LOST_UPDATE_CHECK_TYPE.HELP'
,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\9009\62E9\5982\4F55\4FDD\62A4\6570\636E\4EE5\9632\4E22\5931\66F4\65B0\3002'),
unistr('		\5F53\4E24\4E2A\6216\66F4\591A\4EBA\5458\5C1D\8BD5\66F4\65B0\540C\4E00\6570\636E\5E76\4E14\6700\540E\7684\66F4\65B0\8986\76D6\7B2C\4E00\4E2A\7528\6237\6240\505A\7684\66F4\65B0\6765\4FDD\5B58\66F4\6539\65F6, \66F4\65B0\4F1A\4E22\5931\3002'),
unistr('		\4E3A\9632\6B62\53D1\751F\8FD9\79CD\60C5\51B5, \66F4\65B0\53EF\68C0\67E5\6570\636E\5E93\4E2D\7684\73B0\6709\5217\503C\548C\6700\521D\67E5\8BE2\8BB0\5F55\65F6\68C0\7D22\5230\7684\76F8\5E94\503C\3002</p>'),
unistr('		<p>\4F8B\5982:'),
'          <ol>',
unistr('            <li>\7528\6237 A \67E5\8BE2\96C7\5458 (EMP) \8BB0\5F55\3002</li>'),
unistr('		    <li>\7528\6237 B \67E5\8BE2\76F8\540C\7684\96C7\5458\8BB0\5F55\3002</li>'),
unistr('		    <li>\7528\6237 B \66F4\65B0 EMPNO = 7839 \7684\96C7\5458\8BE6\7EC6\4FE1\606F\5E76\5411\6570\636E\5E93\5E94\7528 (\63D0\4EA4) \66F4\6539\3002</li>'),
unistr('		    <li>\7528\6237 A \66F4\65B0 EMPNO = 7839 \7684\96C7\5458\8BE6\7EC6\4FE1\606F\5E76\5C1D\8BD5\5411\6570\636E\5E93\5E94\7528\66F4\6539\3002</li>'),
'          </ol>',
unistr('          \5982\679C\7528\6237 A \6210\529F\66F4\65B0\76F8\540C\7684\8BB0\5F55, \5219\7528\6237 B \6240\505A\7684\66F4\6539\5C06\4E22\5931\3002</p>'),
unistr('         <p>\5F53\7528\6237 A \5C1D\8BD5\4FDD\5B58\96C7\5458\8BB0\5F55\65F6, \6570\636E\5E93\4E2D\7684\6570\636E\4E0D\540C\4E8E\7528\6237 A \6700\521D\67E5\8BE2\5230\7684\6570\636E\3002'),
unistr('		  \5728\4E0A\9762\7684\6B65\9AA4 1 \4E2D, \53EF\4EE5\6355\83B7\7528\6237 A \6700\521D\67E5\8BE2\7684\5217\503C\3002'),
unistr('		  \7136\540E\5728\4E0A\9762\7684\6B65\9AA4 4 \4E2D, \8FD9\4E9B\503C\53EF\4E0E\6570\636E\5E93\4E2D\7684\5F53\524D\503C\8FDB\884C\6BD4\8F83\3002'),
unistr('		  \6B64\6BD4\8F83\5C06\5BF9\7528\6237 A \5F15\53D1\9519\8BEF, \56E0\4E3A\6570\636E\5E93\503C\7531\7528\6237 B \5728\6B65\9AA4 3 \4E2D\8FDB\884C\4E86\66F4\65B0\3002'),
unistr('		  \8FD9\53EF\9632\6B62\7528\6237\8986\76D6\5176\4ED6\7528\6237\5BF9\76F8\540C\884C\6240\505A\7684\66F4\6539\3002</p>'),
unistr('		  <p>\6CE8 -\201C\4E22\5931\66F4\65B0\7C7B\578B\201D\53EA\6709\5728\5BF9\5E94\7684\5904\7406\201C\4EA4\4E92\5F0F\7F51\683C - \81EA\52A8\884C\5904\7406 (DML)\201D\542F\7528\4E86<strong>\9632\6B62\4E22\5931\66F4\65B0</strong>\65F6\624D\4F1A\4F7F\7528\3002</p>')))
,p_version_scn=>2565957
);
