,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'zh-cn'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>\8981\5728\5458\5DE5\4F4D\4E8E\90E8\95E8 30 \65F6\8FD4\56DE "YES"\FF0C\8BF7\4F7F\7528\4EE5\4E0B\8BED\53E5\FF1A</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 ? "YES" : "NO" );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2565917
);
