,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\5C06\5DF2\4E0A\8F7D\6587\4EF6\5B58\50A8\5728\53EF\901A\8FC7\89C6\56FE APEX_APPLICATION_TEMP_FILES \8BBF\95EE\7684\4E34\65F6\4F4D\7F6E\4E2D\3002&PRODUCT_NAME. \5C06\5728\4F1A\8BDD\7ED3\675F\65F6\6216\4E0A\8F7D\8BF7\6C42\7ED3\675F\65F6\81EA\52A8\5220\9664\6587\4EF6, \5177\4F53\53D6\51B3\4E8E\60A8\4E3A<strong>\6587\4EF6\6E05\9664\4F4D\7F6E</strong>\9009\62E9\7684\5185\5BB9\3002</p>'),
unistr('<p>\5728<strong>\5141\8BB8\591A\4E2A\6587\4EF6</strong>\8BBE\7F6E\4E3A<strong>\5426</strong>\7684\60C5\51B5\4E0B\8BBF\95EE\6587\4EF6:</p>'),
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
unistr('<p>\5728<strong>\5141\8BB8\591A\4E2A\6587\4EF6</strong>\8BBE\7F6E\4E3A<strong>\662F</strong>\7684\60C5\51B5\4E0B\8BBF\95EE\6587\4EF6:</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
