,p_depending_on_expression=>'PLSQL'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<dl><dt>\8981\9488\5BF9\7B26\5408\52A0\85AA\6761\4EF6\7684\5458\5DE5\5C06\85AA\6C34\589E\52A0 3%\FF0C\8BF7\4F7F\7528\4EE5\4E0B\8BED\53E5\FF1A</dt>'),
